* The run/show buttons now use the default .bts-entry style
* to ensure visual consistency. No custom styles are needed.
*/

/* Simulation Palette */
.simulation-palette {
  position: absolute;
  top: 20px;
  left: 80px; /* Positioned to the right of the main palette */
  background: #fff;
  border: 1px solid #ccc;
  border-radius: 4px;
  padding: 5px;
  display: none; /* Hidden by default */
  z-index: 100;
}

.simulation-palette.open {
  display: flex;
  flex-direction: column;
}

.simulation-palette .bts-entry {
  padding: 5px;
  cursor: pointer;
  border-radius: 4px;
  margin: 2px;
  display: flex;
  align-items: center;
  justify-content: center;
  min-width: 30px;
  border: none;
  background: none;
}

.simulation-palette .bts-entry-text {
    font-size: 18px;
    font-weight: bold;
}

.simulation-palette .bts-entry:hover {
  background: #eee;
}

.simulation-palette .bts-entry svg {
  width: 20px;
  height: 20px;
}

.simulation-palette .bts-entry-separator {
  margin: 5px 0;
  border-top: 1px solid #ccc;
  border-bottom: none;
  border-left: none;
  border-right: none;
  padding: 0;
}


/* Overlays */
.simulation-overlay-text {
  background: rgba(0, 0, 0, 0.7);
  color: white;
  padding: 2px 5px;
  border-radius: 4px;
  font-size: 12px;
  white-space: nowrap;
}

/* Heatmap container */
.heatmap-shown svg {
    overflow: visible !important;
}

.heatmap-shown .heatmap-canvas {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    pointer-events: none;
    mix-blend-mode: multiply;
    opacity: 0.7;
}

/* Chart Panel */
.simulation-chart-panel {
  position: absolute;
  bottom: 20px;
  right: 20px;
  background: #fff;
  border: 1px solid #ccc;
  border-radius: 4px;
  padding: 10px;
  display: none;
  z-index: 100;
  width: 1000px;
  box-shadow: 0 5px 15px rgba(0,0,0,0.2);
}

.simulation-chart-panel.open {
  display: block;
}

.simulation-chart-panel .header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  border-bottom: 1px solid #eee;
  padding-bottom: 5px;
  margin-bottom: 10px;
  font-weight: bold;
}

.simulation-chart-panel .header .close,
.simulation-chart-panel .header .help-button,
.simulation-chart-panel .header .schedule-button {
  background: none;
  border: none;
  cursor: pointer;
  padding: 0 5px;
}

.simulation-chart-panel .header .help-button svg,
.simulation-chart-panel .header .schedule-button svg {
    width: 18px;
    height: 18px;
}

.simulation-chart-panel .header .close {
  font-size: 20px;
}

.simulation-chart-panel .help-content {
    padding: 10px;
    border-top: 1px solid #eee;
}

.simulation-chart-panel .help-content.hidden,
.simulation-chart-panel .content.hidden,
.simulation-chart-panel .html-content.hidden {
    display: none;
}

/* Styles for HTML Table Views */
.simulation-chart-panel .content {
    max-height: 60vh; /* Limit height to 60% of viewport height */
    overflow-y: auto; /* Add vertical scroll if content overflows */
}

.simulation-chart-panel .html-content {
    width: 100%;
    height: 100%;
    overflow: auto; /* Scrollbars for the table container itself */
}

.sim-results-table {
    width: 100%;
    border-collapse: collapse;
    table-layout: fixed; /* Prevent table from expanding uncontrollably */
}

.sim-results-table th,
.sim-results-table td {
    border: 1px solid #ddd;
    padding: 8px;
    text-align: left;
    word-wrap: break-word; /* Wrap long text */
}

.sim-results-table th {
    background-color: #f2f2f2;
    font-weight: bold;
}

.sim-results-table tbody tr:nth-child(even) {
    background-color: #f9f9f9;
}

.simulation-chart-panel canvas.hidden {
    display: none;
}

/* Schedule Modal */
.schedule-modal-overlay,
.plan-breakdown-modal-overlay {
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: rgba(0, 0, 0, 0.6);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 1002; /* Above chart panel */
}

.schedule-modal-overlay.hidden,
.plan-breakdown-modal-overlay.hidden {
    display: none;
}

.schedule-modal {
    background: #fff;
    padding: 20px;
    border-radius: 8px;
    box-shadow: 0 5px 15px rgba(0,0,0,0.3);
    width: 90%;
    max-width: 600px;
}

.schedule-modal-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    border-bottom: 1px solid #eee;
    padding-bottom: 10px;
    margin-bottom: 15px;
}

.schedule-modal-header h3 {
    margin: 0;
    font-size: 1.2em;
}

.schedule-modal-header .close-modal {
    background: none;
    border: none;
    font-size: 24px;
    cursor: pointer;
    padding: 0 5px;
}

.schedule-modal-content h4 {
    margin-top: 0;
    margin-bottom: 10px;
}

.schedule-modal-content ul {
    list-style-type: none;
    padding-left: 0;
}

.schedule-modal-content li {
    background: #f4f4f4;
    padding: 8px;
    border-radius: 4px;
    margin-bottom: 5px;
}

.header-buttons {
    display: flex;
    align-items: center;
}

.header-buttons button {
    margin-left: 5px;
}

.plan-breakdown-button {
    background: #e0e0e0;
    border: 1px solid #ccc;
    border-radius: 4px;
    padding: 2px 8px;
    cursor: pointer;
}

.plan-breakdown-button.hidden {
    display: none;
}

.work-plan-details {
    display: flex;
    justify-content: space-around;
    gap: 20px;
}

.work-plan-table {
    flex: 1;
}

.sim-summary-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 15px;
  padding-top: 10px;
}

.sim-summary-grid .sim-summary-item {
  display: flex;
  flex-direction: column;
  background: #f9f9f9;
  padding: 10px;
  border-radius: 5px;
  border-left: 4px solid #1565c0; /* Accent color */
}

.sim-summary-grid .sim-summary-item .label {
  font-weight: bold;
  color: #333;
  font-size: 0.9em;
  margin-bottom: 5px;
}

.sim-summary-grid .sim-summary-item .value {
  font-size: 1.2em;
  color: #1565c0;
  font-weight: bold;
}
